using System.Collections;
using IdleIntelligence.Core;
using UnityEngine;
using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // One bounded visual receipt. The saved equipment is never changed here.
 public sealed class EquipFlight:MonoBehaviour {
  Coroutine running;GameObject layer;ItemPortrait target;string caption;bool changedIncome,changedData;
  public bool IsAnimating=>running!=null;
  public void Cancel(){if(running!=null)StopCoroutine(running);running=null;if(target!=null){target.Art.canvasRenderer.SetAlpha(1);target.Caption.text=caption;}if(layer!=null){layer.SetActive(false);Destroy(layer);}layer=null;target=null;}
  void OnDisable()=>Cancel();
  public void Play(ItemPortrait prefab,ItemInstance item,Vector3 origin,ItemPortrait destination,string effect,bool reduced,bool incomeChanged=false,bool dataChanged=false){Cancel();changedIncome=incomeChanged;changedData=dataChanged;if(reduced||destination==null)return;target=destination;caption=target.Caption.text;layer=WorkshopUIFactory.Node("EquipmentFlightLayer",GetComponentInParent<Canvas>().transform);WorkshopUIFactory.Fill((RectTransform)layer.transform);layer.transform.SetAsLastSibling();running=StartCoroutine(Fly(prefab,item,origin,effect));}
  IEnumerator Fly(ItemPortrait prefab,ItemInstance item,Vector3 origin,string effect){Canvas.ForceUpdateCanvases();var scroll=target.GetComponentInParent<ScrollRect>();if(scroll!=null&&!scroll.viewport.rect.Contains((Vector2)scroll.viewport.InverseTransformPoint(target.Frame.transform.position))){float y=-scroll.content.InverseTransformPoint(target.Frame.transform.position).y;scroll.verticalNormalizedPosition=Mathf.Clamp01(1-(y-scroll.viewport.rect.height*.4f)/Mathf.Max(1,scroll.content.rect.height-scroll.viewport.rect.height));Canvas.ForceUpdateCanvases();}var root=(RectTransform)layer.transform;var ghost=Instantiate(prefab,root);ghost.name="EquippingItem";ghost.ShowLevel=false;ghost.Bind(item);ghost.Button.interactable=false;foreach(var g in ghost.GetComponentsInChildren<Graphic>())g.raycastTarget=false;var r=(RectTransform)ghost.transform;r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(130,130);Vector2 start=root.InverseTransformPoint(origin),end=root.InverseTransformPoint(target.Frame.transform.position);target.Art.canvasRenderer.SetAlpha(0);PixelImpact.Play(target.Frame.transform,"TargetLock",Vector2.zero,110,ItemPortrait.RarityColor(item.rarity),.18f);float time=0;double began=ReceiptMotion.Now;while(time<.46f){time=ReceiptMotion.Age(began);float t=Mathf.Clamp01(time/.46f),p=ReceiptMotion.Ease(t);r.anchoredPosition=ReceiptMotion.Arc(start,end,p,38);r.sizeDelta=Vector2.Lerp(new Vector2(130,130),target.Frame.rectTransform.rect.size*.85f,p);yield return null;}ghost.gameObject.SetActive(false);target.Art.canvasRenderer.SetAlpha(1);PixelImpact.Play(target.Frame.transform,"EquipLatch",Vector2.zero,100,ItemPortrait.RarityColor(item.rarity));var model=target.GetComponentInParent<ModelLoadout>();model?.Receipt(false,changedIncome,changedData);UnityEngine.Object.FindFirstObjectByType<GameRuntime>()?.Audio?.Play("unlock");if(model!=null){var line=WorkshopUIFactory.Node("SocketToCoreWave",root,typeof(Image)).GetComponent<Image>();line.raycastTarget=false;line.sprite=Resources.Load<PresentationArt>("PixelUI/PresentationArt").Steam;line.color=GameTheme.Accent;line.rectTransform.sizeDelta=new Vector2(14,7);Vector2 core=root.InverseTransformPoint(model.Core.transform.position);for(float phase=0;phase<.2f;phase+=Time.unscaledDeltaTime){line.rectTransform.anchoredPosition=ReceiptMotion.Arc(end,core,ReceiptMotion.Ease(phase/.2f),12);yield return null;}Destroy(line.gameObject);}var label=WorkshopUIFactory.Label("EquipmentEffectReceipt",root,System.Text.RegularExpressions.Regex.Replace(effect,"<.*?>","").Replace("\n"," · "),14);Destroy(label.GetComponent<LayoutElement>());var lr=label.rectTransform;lr.anchorMin=new Vector2(.05f,.13f);lr.anchorMax=new Vector2(.95f,.13f);lr.sizeDelta=new Vector2(0,54);lr.anchoredPosition=Vector2.zero;label.alignment=TextAnchor.MiddleCenter;label.color=ItemPortrait.RarityColor(item.rarity);target.Caption.text=caption+" ✓";yield return new WaitForSecondsRealtime(.6f);running=null;Cancel();}
 }
}
